// ─── File: StoryBankDemo.java ───
// Single runnable file with multiple top-level, package-private classes.

import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Handler;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class StoryBankDemo {

    private static final Logger log = Logger.getLogger(StoryBankDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger rootLogger = Logger.getLogger("");
        for (Handler handler : rootLogger.getHandlers()) {
            rootLogger.removeHandler(handler);
        }
        ConsoleHandler consoleHandler = new ConsoleHandler();
        consoleHandler.setFormatter(new BankLogFormatter());
        consoleHandler.setLevel(Level.ALL);
        rootLogger.addHandler(consoleHandler);
        rootLogger.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info(() -> "Building a reusable STAR story bank at " + BANK_NAME);

        StoryBank bank = new StoryBank();
        bank.add(new PreparedStory("Rescued the failing transfer system",
                Set.of("leadership", "pressure", "technical-decision", "ownership")));
        bank.add(new PreparedStory("Mentored a junior on BigDecimal for money",
                Set.of("mentoring", "conflict", "quality")));
        bank.add(new PreparedStory("Drove the monolith-to-service migration",
                Set.of("technical-decision", "migration", "influence", "leadership")));
        bank.add(new PreparedStory("Underestimated multi-currency effort",
                Set.of("failure", "estimation", "communication")));

        // One story answering multiple question types:
        for (String category : List.of("leadership", "failure", "conflict", "technical-decision")) {
            PreparedStory match = bank.bestFor(category);
            if (match != null) {
                log.info(() -> "Question category '" + category + "' -> use story: '"
                        + match.getTitle() + "'");
            } else {
                log.warning(() -> "No prepared story covers '" + category + "'. Prepare one.");
            }
        }

        PreparedStory mostVersatile = bank.mostVersatile();
        log.info(() -> "Most versatile story to rehearse deeply: '" + mostVersatile.getTitle()
                + "' (covers " + mostVersatile.getCategories().size() + " categories).");
    }
}

// ─── Would be in model/PreparedStory.java in a real project ───
class PreparedStory {
    private final String title;
    private final Set<String> categories;

    PreparedStory(String title, Set<String> categories) {
        this.title = title;
        this.categories = categories;
    }

    String getTitle() { return title; }
    Set<String> getCategories() { return categories; }
    boolean covers(String category) { return categories.contains(category); }
}

// ─── Would be in bank/StoryBank.java in a real project ───
class StoryBank {
    private static final Logger log = Logger.getLogger(StoryBank.class.getName());
    private final List<PreparedStory> stories = new ArrayList<>();

    void add(PreparedStory story) {
        stories.add(story);
        log.fine(() -> "Added story '" + story.getTitle() + "' covering " + story.getCategories());
    }

    // Return the story covering this category that covers the most categories overall,
    // so you reuse your richest material.
    PreparedStory bestFor(String category) {
        PreparedStory best = null;
        for (PreparedStory s : stories) {
            if (s.covers(category)) {
                if (best == null || s.getCategories().size() > best.getCategories().size()) {
                    best = s;
                }
            }
        }
        return best;
    }

    PreparedStory mostVersatile() {
        PreparedStory best = null;
        for (PreparedStory s : stories) {
            if (best == null || s.getCategories().size() > best.getCategories().size()) {
                best = s;
            }
        }
        return best;
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tY-%1$tm-%1$td %1$tH:%1$tM:%1$tS.%1$tL %2$-7s [%3$s] %4$s%n",
                record.getMillis(),
                record.getLevel().getName(),
                record.getSourceClassName() != null
                        ? record.getSourceClassName().substring(
                                record.getSourceClassName().lastIndexOf('.') + 1)
                        : "Unknown",
                record.getMessage());
    }
}
